  dist=np.full(T.shape,999);q=deque()
  for r,c in np.argwhere(T==mask_val):
   r,c=int(r),int(c)
   if any(0<=r+dr<20 and 0<=c+dc<20 and T[r+dr,c+dc]==v for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]):dist[r,c]=1;q.append((r,c))
  while q:
   r,c=q.popleft()
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    rr,cc=r+dr,c+dc
    if 0<=rr<20 and 0<=cc<20 and T[rr,cc]==mask_val and dist[rr,cc]>dist[r,c]+1:dist[rr,cc]=dist[r,c]+1;q.append((rr,cc))
  distmap[v]=dist
 return distmap
