 steps=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
 dist=np.full(A.shape,999);q=deque()
 for r,c in np.argwhere(A==mask_val):
  r,c=int(r),int(c)
  if any(0<=r+dr<A.shape[0] and 0<=c+dc<A.shape[1] and A[r+dr,c+dc]==src_val for dr,dc in steps):dist[r,c]=1;q.append((r,c))
 while q:
  r,c=q.popleft()
  for dr,dc in steps:
   rr,cc=r+dr,c+dc
   if 0<=rr<A.shape[0] and 0<=cc<A.shape[1] and A[rr,cc]==mask_val and dist[rr,cc]>dist[r,c]+1:dist[rr,cc]=dist[r,c]+1;q.append((rr,cc))
 return dist
